package ru.denis.forts3d.item;
import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.*;import net.minecraft.world.item.*;import net.minecraft.world.level.Level;import ru.denis.forts3d.game.*;
public class TeamSelectorItem extends Item {public TeamSelectorItem(Properties p){super(p);} @Override public InteractionResultHolder<ItemStack> use(Level l,net.minecraft.world.entity.player.Player p,InteractionHand h){if(!l.isClientSide&&p instanceof ServerPlayer sp){var m=FortsMatchManager.get(sp.server);FortsTeam next=m.teamOf(sp.getUUID())==FortsTeam.RED?FortsTeam.BLUE:FortsTeam.RED;m.join(sp,next);sp.sendSystemMessage(Component.literal(next.color()+"Вы вступили в команду "+next.id()));}return InteractionResultHolder.sidedSuccess(p.getItemInHand(h),l.isClientSide);}}
